/**
 * Janson's Losar table — Gregorian dates of Tibetan New Year for the 16th and 17th rabjung
 * cycles, 1927-2046, with each year's element-animal name.
 *
 * @remarks
 * A table of dates: facts, not copyrightable expression, and therefore usable directly as a
 * fixture under this project's clean-room constraint. Transcribed mechanically from the paper's
 * LaTeX source.
 *
 * This is the primary correctness gate for the whole engine. Losar exercises the month count,
 * the leap-month rule, the day-labelling rule and the true-date astronomy at once, and it is
 * sensitive to all of them: the year may open with a leap month 1 (2000 does) and its first day
 * may be day 2 when day 1 is skipped.
 */
export interface LosarRow {
	/** Janson's *Y* — the Gregorian year the Tibetan year begins in. */
	year: number;
	/** ISO date of the first day of the Tibetan year. */
	losar: string;
	/** The year's element-animal name, lowercased, e.g. "fire-horse". */
	name: string;
}

